/// 응답을 기다리며 멈춘다. 두 번 이상 호출하면 두 번째부터 무시된다.
/// \code
/// [service setAcceptUserHandler:^(NSString *userKey, APHAcceptUserCompletion completion) {
///     completion(YES, nil, nil);          // 이용 가능
///     // completion(NO, @"미성년 이용 불가", nil);
